CREATE TABLE procurement_purchases (cycle_id TEXT NOT NULL, sku_id TEXT NOT NULL REFERENCES catalog_skus(id), purchased_quantity INTEGER NOT NULL CHECK (purchased_quantity >= 0), updated_at TEXT NOT NULL, PRIMARY KEY (cycle_id, sku_id));
CREATE TABLE procurement_shortages (id TEXT PRIMARY KEY NOT NULL, cycle_id TEXT NOT NULL, sku_id TEXT NOT NULL REFERENCES catalog_skus(id), requested_quantity INTEGER NOT NULL CHECK (requested_quantity > 0), available_quantity INTEGER NOT NULL CHECK (available_quantity >= 0), status TEXT NOT NULL CHECK (status IN ('open', 'resolved')), created_at TEXT NOT NULL);
CREATE TABLE procurement_substitutions (id TEXT PRIMARY KEY NOT NULL, shortage_id TEXT NOT NULL REFERENCES procurement_shortages(id), original_sku_id TEXT NOT NULL, substitute_sku_id TEXT NOT NULL REFERENCES catalog_skus(id), quantity INTEGER NOT NULL CHECK (quantity > 0), status TEXT NOT NULL CHECK (status IN ('proposed', 'approved', 'rejected')), approved_at TEXT);
CREATE TABLE packing_manifests (id TEXT PRIMARY KEY NOT NULL, cycle_id TEXT NOT NULL, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), status TEXT NOT NULL CHECK (status IN ('pending', 'packed', 'exception')), created_at TEXT NOT NULL);
CREATE TABLE dispatch_assignments (id TEXT PRIMARY KEY NOT NULL, cycle_id TEXT NOT NULL, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), window_id TEXT NOT NULL REFERENCES delivery_windows(id), deliveryman_user_id TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('assigned', 'out_for_delivery', 'delivered', 'failed')), assigned_at TEXT NOT NULL);
CREATE INDEX dispatch_cycle_idx ON dispatch_assignments (cycle_id, assigned_at);
